total = WARMUP_COUNT + MEASURED_COUNT
consecutive_preaccept_rejections = 0

for ordinal in range(1, total + 1):
    if time.monotonic() >= condition_deadline:
        stop_reason = "condition_deadline"
        break
    if _sha256(manifest_path.read_bytes()) != manifest_hash:

except K2CaseError as exc:
    partial = exc.partial_record or {}
    row["stages"] = partial.get("stages", {})
    row["correctness"] = partial.get("correctness", {})
    row["partial_quality_incorrect"] = any(
        partial.get("correctness", {}).get(key) is False
        for key in ("transcript_matches_reference_words", "assistant_reply_matches_expected_words")
    )
    if row["partial_quality_incorrect"]:
        row["partial_failure_class"] = "quality_predicate_failed_before_full_flow_completion"
    raise CampaignFailure(
        exc.stage, exc.category, stop=exc.stop_campaign or phase == "warmup"
    ) from None

if phase == "measured":
    if row.get("failure", {}).get("code") == "preaccept_capability_changed":
        consecutive_preaccept_rejections += 1
    else:
        consecutive_preaccept_rejections = 0
    row["consecutive_preaccept_rejections"] = consecutive_preaccept_rejections
    if consecutive_preaccept_rejections >= 3:
        abort_after_row = True
        stop_reason = "three_consecutive_preaccept_capability_rejections"
row_name = f"attempt-{ordinal:04d}-{phase}.jsonl"
_write_once(attempts_dir / row_name, (json.dumps(row, sort_keys=True, ensure_ascii=False) + "\n").encode())

def fail(stage: str, category: str, *, duration_ms: float | None = None,
         stop_campaign: bool = False, status: int | None = None,
         preaccept_response: dict[str, Any] | None = None) -> None:
    record["status"] = "failed"
    record["failure"] = {"stage": stage, "category": category,
                         "http_status": status}
    if stage not in record["stages"]:
        record["stages"][stage] = {"status": "failed", "error_category": category}
    if duration_ms is not None:
        record["stages"][stage].setdefault("duration_ms", duration_ms)
    if preaccept_response is not None:
        record["stages"][stage]["preaccept_response"] = preaccept_response
    raise K2CaseError(stage, category, duration_ms=duration_ms,
                      stop_campaign=stop_campaign, status=status,
                      partial_record=record)
